# Let's look at the patterns more carefully
inputs = ['aa', 'uwb', 'kg', 'fidu', 'ya']
outputs = ['aa', 'uwb', 'ki', 'fidu', 'za']

print("Input -> Output:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")

# Let's see what needs to change
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"Change needed in position {i}: '{inp}' -> '{out}'")
        # Find differences
        for j, (a, b) in enumerate(zip(inp, out)):
            if a != b:
                print(f"  Position {j}: '{a}' -> '{b}'")
        if len(inp) != len(out):
            print(f"  Length changed: {len(inp)} -> {len(out)}")

